/**
 * The demo clock. PRD sections 11 and 13.
 *
 * Every time-derived value in the product (days remaining, yields, due status,
 * the maturity ladder) is computed from this clock rather than from the wall
 * clock or from a stored column. PRD section 13 is explicit that "tenor,
 * remaining days, percentages, and yields are derived rather than independently
 * editable values", and section 11 lets any viewer fast-forward the world, so a
 * stored day count would be wrong the moment someone pressed +30 days.
 *
 * Dates here are business dates, not instants. A payable matures on a date, not
 * at a time of day, so the whole module works in calendar days on UTC midnight
 * and never touches a local timezone. That keeps the booth laptop and the
 * tablet in agreement regardless of where either is set.
 */

/** A business date as `YYYY-MM-DD`. */
export type IsoDate = string & { readonly __brand: 'IsoDate' };

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

export function parseIsoDate(value: string): IsoDate {
  if (!ISO_DATE.test(value)) {
    throw new RangeError(`expected a YYYY-MM-DD date, received ${JSON.stringify(value)}`);
  }
  const ms = Date.parse(`${value}T00:00:00Z`);
  if (Number.isNaN(ms)) {
    throw new RangeError(`not a real calendar date: ${value}`);
  }
  return value as IsoDate;
}

const MS_PER_DAY = 86_400_000;

function toUtcMs(date: IsoDate): number {
  return Date.parse(`${date}T00:00:00Z`);
}

function fromUtcMs(ms: number): IsoDate {
  return new Date(ms).toISOString().slice(0, 10) as IsoDate;
}

/** Whole calendar days from `from` to `to`. Negative when `to` is in the past. */
export function daysBetween(from: IsoDate, to: IsoDate): number {
  return Math.round((toUtcMs(to) - toUtcMs(from)) / MS_PER_DAY);
}

export function addDays(date: IsoDate, days: number): IsoDate {
  if (!Number.isInteger(days)) {
    throw new RangeError(`addDays expects whole days, received ${days}`);
  }
  return fromUtcMs(toUtcMs(date) + days * MS_PER_DAY);
}

/**
 * The world's current position in time.
 *
 * `t0` is the seed date and never moves; `offsetDays` is everything the demo
 * controls have added. Holding the offset separately rather than mutating a
 * single date means "reset world" is a single assignment back to zero and the
 * seeded relative dates in PRD section 12 stay meaningful.
 */
export interface DemoClock {
  readonly t0: IsoDate;
  readonly offsetDays: number;
}

export function clockAt(t0: IsoDate, offsetDays = 0): DemoClock {
  if (!Number.isInteger(offsetDays)) {
    throw new RangeError(`offsetDays must be whole days, received ${offsetDays}`);
  }
  return { t0, offsetDays };
}

/** Today, as the demo world sees it. */
export function today(clock: DemoClock): IsoDate {
  return addDays(clock.t0, clock.offsetDays);
}

/**
 * `d` in the PRD section 6 pricing formulas. Zero on the maturity date,
 * negative after it.
 */
export function daysRemaining(clock: DemoClock, maturityDate: IsoDate): number {
  return daysBetween(today(clock), maturityDate);
}

/**
 * Original tenor, which PRD section 6 requires be displayed separately from
 * days remaining and does not change as the clock advances.
 */
export function tenorDays(issueDate: IsoDate, maturityDate: IsoDate): number {
  return daysBetween(issueDate, maturityDate);
}

/** The fast-forward steps offered in PRD section 11. */
export const FAST_FORWARD_STEPS = [1, 30] as const;

export function advance(clock: DemoClock, days: number): DemoClock {
  if (!Number.isInteger(days) || days < 0) {
    throw new RangeError(`the demo clock only moves forward in whole days, received ${days}`);
  }
  return { ...clock, offsetDays: clock.offsetDays + days };
}

/**
 * "Jump to next maturity" from PRD section 11.
 *
 * Returns the clock unchanged when nothing is still ahead of it, so pressing
 * the control on a fully matured world is a no-op rather than an error. That
 * matters because the control sits on a bar the presenter may hit mid-sentence.
 */
export function jumpToNextMaturity(clock: DemoClock, maturityDates: readonly IsoDate[]): DemoClock {
  const now = today(clock);
  const ahead = maturityDates
    .map((date) => daysBetween(now, date))
    .filter((days) => days > 0)
    .sort((a, b) => a - b);
  const next = ahead[0];
  return next === undefined ? clock : advance(clock, next);
}

export function reset(clock: DemoClock): DemoClock {
  return { ...clock, offsetDays: 0 };
}

/** Format for the demo-controls bar, e.g. "14 Sep 2026 (T0 + 30d)". */
export function formatClock(clock: DemoClock): string {
  const date = new Date(`${today(clock)}T00:00:00Z`);
  const shown = date.toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    timeZone: 'UTC',
  });
  return clock.offsetDays === 0 ? `${shown} (T0)` : `${shown} (T0 + ${clock.offsetDays}d)`;
}

/**
 * Render days remaining for a table cell.
 *
 * PRD section 6 replaces a forward yield with "Due" or "Overdue" at or after
 * maturity; the same substitution applies to the day count so a row never shows
 * a negative number of days.
 */
export function formatDaysRemaining(days: number): string {
  if (days > 0) return `${days}d`;
  return days === 0 ? 'Due' : `Overdue ${Math.abs(days)}d`;
}

src/core/market.ts.source:
/**
 * Marketplace filtering and sorting. PRD §8 screen 9.
 *
 *   "filter by maturity, tenor, sample grade, ticket size, and yield.
 *    Default sort is yield."
 *
 * Filtering happens here, in TypeScript, rather than in the SQL that fetches
 * listings. Three of the five criteria — tenor, yield, and the maturity cutoff
 * — are derived from the demo clock and the §6 pricing formulas, which live in
 * `src/core/pricing.ts`. Pushing them into SQL would mean a second
 * implementation of the yield formula that has to agree with the first
 * forever, and the two would drift the first time §6 was revisited. The
 * marketplace is a demo order book of tens of lots, so the cost of filtering
 * in memory is nothing and the cost of a duplicate formula is real.
 *
 * The filter is a plain object parsed from the URL query, so a filtered view is
 * a shareable link and the back button behaves. Nothing here touches React or
 * the database.
 */

import { type BaseUnits, BASE_UNITS_PER_UNIT } from './money';
import type { IsoDate } from './clock';

export const GRADES = ['AAA', 'AA', 'A'] as const;
export type Grade = (typeof GRADES)[number];

export const SORTS = ['yield', 'maturity', 'tenor', 'size', 'price'] as const;
export type Sort = (typeof SORTS)[number];

export const SORT_LABEL: Record<Sort, string> = {
  yield: 'Yield, highest first',
  maturity: 'Maturity, soonest first',
  tenor: 'Tenor, shortest first',
  size: 'Ticket size, largest first',
  price: 'Price, cheapest first',
};

export interface MarketFilter {
  /** Only lots maturing on or before this date. */
  maturityBy: IsoDate | null;
  /** Days remaining, inclusive on both ends. */
  tenorMin: number | null;
  tenorMax: number | null;
  /** Empty means every grade, which is not the same as none of them. */
  grades: readonly Grade[];
  /** Listed face, in base units. */
  sizeMin: BaseUnits | null;
  sizeMax: BaseUnits | null;
  /** Annualised lender yield, in percent. */
  yieldMin: number | null;
  sort: Sort;
}

export const NO_FILTER: MarketFilter = {
  maturityBy: null,
  tenorMin: null,
  tenorMax: null,
  grades: [],
  sizeMin: null,
  sizeMax: null,
  yieldMin: null,
  sort: 'yield',
};

/** The shape a listing has to have to be filtered. Narrower than `Listing`. */
export interface Filterable {
  grade: string | null;
  listedFaceBase: BaseUnits;
  maturityDate: IsoDate;
  quote: { daysRemaining: number; lenderYieldPercent: number | null; pricePercent: number };
}

export function applyFilter<T extends Filterable>(
  listings: readonly T[],
  filter: MarketFilter,
): T[] {
  const kept = listings.filter((l) => {
    if (filter.maturityBy !== null && l.maturityDate > filter.maturityBy) return false;
    if (filter.tenorMin !== null && l.quote.daysRemaining < filter.tenorMin) return false;
    if (filter.tenorMax !== null && l.quote.daysRemaining > filter.tenorMax) return false;
    if (filter.grades.length > 0 && !filter.grades.includes(l.grade as Grade)) return false;
    if (filter.sizeMin !== null && l.listedFaceBase < filter.sizeMin) return false;
    if (filter.sizeMax !== null && l.listedFaceBase > filter.sizeMax) return false;
    // A matured lot has no forward yield (§6 shows "Due" instead), so a yield
    // floor excludes it rather than treating a missing yield as zero.
    if (filter.yieldMin !== null) {
      if (l.quote.lenderYieldPercent === null) return false;
      if (l.quote.lenderYieldPercent < filter.yieldMin) return false;
    }
    return true;
  });
  return sortListings(kept, filter.sort);
}

function sortListings<T extends Filterable>(listings: T[], sort: Sort): T[] {
  const by: Record<Sort, (a: T, b: T) => number> = {
    yield: (a, b) => (b.quote.lenderYieldPercent ?? -1) - (a.quote.lenderYieldPercent ?? -1),
    maturity: (a, b) => a.maturityDate.localeCompare(b.maturityDate),
    tenor: (a, b) => a.quote.daysRemaining - b.quote.daysRemaining,
    size: (a, b) => (a.listedFaceBase < b.listedFaceBase ? 1 : a.listedFaceBase > b.listedFaceBase ? -1 : 0),
    price: (a, b) => a.quote.pricePercent - b.quote.pricePercent,
  };
  return [...listings].sort(by[sort]);
}

/** True when the filter would change what a lender sees. Drives the Clear control. */
export function isFiltered(filter: MarketFilter): boolean {
  return (
    filter.maturityBy !== null ||
    filter.tenorMin !== null ||
    filter.tenorMax !== null ||
    filter.grades.length > 0 ||
    filter.sizeMin !== null ||
    filter.sizeMax !== null ||
    filter.yieldMin !== null
  );
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Read a filter out of a URL query.
 *
 * Anything unparseable is dropped rather than rejected. A hand-edited or stale
 * link should show the marketplace, not an error page: this is a browse
 * control, and the worst outcome of ignoring a bad value is that the lender
 * sees more lots than they asked for and can see why from the controls.
 */
export function parseFilter(params: Record<string, string | string[] | undefined>): MarketFilter {
  const one = (key: string): string | null => {
    const v = params[key];
    const s = Array.isArray(v) ? v[0] : v;
    return s === undefined || s === '' ? null : s;
  };

  const int = (key: string): number | null => {
    const s = one(key);
    if (s === null) return null;
    const n = Number(s);
    return Number.isFinite(n) ? Math.trunc(n) : null;
  };

  const num = (key: string): number | null => {
    const s = one(key);
    if (s === null) return null;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  };

  /** Display units in the URL, base units in the filter. `250000` reads as 250,000 XUSD. */
  const units = (key: string): BaseUnits | null => {
    const n = num(key);
    if (n === null || n < 0) return null;
    return (BigInt(Math.round(n * Number(BASE_UNITS_PER_UNIT))) as BaseUnits);
  };

  const maturityRaw = one('by');
  const gradesRaw = one('grade');
  const sortRaw = one('sort');

  return {
    maturityBy: maturityRaw !== null && ISO_DATE.test(maturityRaw) ? (maturityRaw as IsoDate) : null,
    tenorMin: int('tmin'),
    tenorMax: int('tmax'),
    grades:
      gradesRaw === null
        ? []
        : gradesRaw.split(',').filter((g): g is Grade => (GRADES as readonly string[]).includes(g)),
    sizeMin: units('smin'),
    sizeMax: units('smax'),
    yieldMin: num('ymin'),
    sort: (SORTS as readonly string[]).includes(sortRaw ?? '') ? (sortRaw as Sort) : 'yield',
  };
}

src/core/pricing.ts.source:
/**
 * The pricing convention from PRD section 6.
 *
 * "Use one calculation across listings, offers, dashboards, and the runbook."
 * That sentence is the reason this module exists and the reason it is pure.
 * Every screen that shows a price, a discount or a yield calls {@link quote}.
 * There is no second implementation to drift from this one.
 *
 * `F` and `P` always apply to the quantity being priced, never automatically to
 * the original invoice face. Callers pass the face of the listed quantity.
 */

import {
  BPS_PER_100_PERCENT,
  type BaseUnits,
  type PercentBps,
  gt,
  isPositive,
  mulDivRound,
  sub,
} from './money';

/**
 * Where a payable sits relative to its maturity date.
 *
 * PRD section 6: "At or after maturity, show 'Due' or 'Overdue' instead of
 * calculating a forward yield." Whether a past-due payable is reported as
 * Overdue also depends on whether it settled, which is lifecycle state rather
 * than arithmetic, so this type reports only what the clock can prove.
 */
export type MaturityState = 'live' | 'due' | 'past-due';

export function maturityState(daysRemaining: number): MaturityState {
  if (daysRemaining > 0) return 'live';
  return daysRemaining === 0 ? 'due' : 'past-due';
}

/**
 * The complete economics of one priced quantity.
 *
 * Returned as a whole rather than as five separate helpers because every
 * surface in the PRD shows these together, and a caller assembling them one
 * call at a time is how two screens end up disagreeing.
 *
 * The two annualised measures carry different denominators and must keep their
 * distinct labels (PRD section 6). They are deliberately named for what they
 * measure rather than shortened to a shared "yield".
 */
export interface Quote {
  /** `F`. XUSD face of the quantity being priced. */
  readonly face: BaseUnits;
  /** `P`. XUSD purchase price for that quantity. */
  readonly price: BaseUnits;
  /** `F - P`. */
  readonly discount: BaseUnits;
  /** `100 * P / F`, for display. */
  readonly pricePercent: number;
  /** `d`. Remaining calendar days to maturity, from the demo clock. */
  readonly daysRemaining: number;
  readonly maturity: MaturityState;
  /**
   * `100 * (F - P) / F * 365 / d`. The supplier's cost of financing.
   * Null at or after maturity, where a forward rate has no meaning.
   */
  readonly annualisedDiscountCostPercent: number | null;
  /**
   * `100 * (F - P) / P * 365 / d`. The lender's return on cash deployed.
   * Null at or after maturity.
   */
  readonly lenderYieldPercent: number | null;
}

/** Actual/365, no compounding, no fees. PRD section 6. */
const DAYS_PER_YEAR = 365;

/**
 * Convert a percent-of-face entry into a whole number of base units.
 *
 * PRD section 9: "percentage-of-face entry converts to the same amount using
 * listed face as `F`". The base-unit result is the canonical stored price; the
 * percentage is only ever an input or a display value. Rounding is half away
 * from zero, shared with every other rounding decision in the system.
 */
export function priceFromPercent(face: BaseUnits, percent: PercentBps): BaseUnits {
  if (!Number.isInteger(percent) || percent < 0) {
    throw new RangeError(`percent must be a non-negative whole number of basis points, received ${percent}`);
  }
  return mulDivRound(face, BigInt(percent), BigInt(BPS_PER_100_PERCENT));
}

/**
 * `100 * P / F` as a display number.
 *
 * Returns a float on purpose: this value is shown, never stored and never fed
 * back into an amount. The money path stays in base units.
 */
export function percentOfFace(price: BaseUnits, face: BaseUnits): number {
  if (!isPositive(face)) {
    throw new RangeError('face must be positive to express a price as a percentage of it');
  }
  return (Number(price) / Number(face)) * 100;
}

/**
 * Build the full economics for one priced quantity.
 *
 * @param face  `F`, the XUSD face of the quantity being priced.
 * @param price `P`, the XUSD price for that same quantity.
 * @param daysRemaining `d`, from the demo clock. May be zero or negative.
 */
export function quote(face: BaseUnits, price: BaseUnits, daysRemaining: number): Quote {
  if (!isPositive(face)) {
    throw new RangeError('face must be positive');
  }
  if (!Number.isInteger(daysRemaining)) {
    throw new RangeError(`daysRemaining must be a whole number of days, received ${daysRemaining}`);
  }
  const discount = sub(face, price);
  const maturity = maturityState(daysRemaining);
  const annualise = maturity === 'live';

  return {
    face,
    price,
    discount,
    pricePercent: percentOfFace(price, face),
    daysRemaining,
    maturity,
    annualisedDiscountCostPercent: annualise
      ? (Number(discount) / Number(face)) * 100 * (DAYS_PER_YEAR / daysRemaining)
      : null,
    lenderYieldPercent:
      annualise && isPositive(price)
        ? (Number(discount) / Number(price)) * 100 * (DAYS_PER_YEAR / daysRemaining)
        : null,
  };
}

/**
 * Find the price that produces a target lender yield, for the indicative price
 * a supplier is offered before they name their own (PRD section 8, screen 7).
 *
 * Derived from `y = (F - P) / P * 365 / d` solved for `P`:
 *   P = F / (1 + y * d / 365)
 */
export function priceForTargetYield(face: BaseUnits, targetYieldPercent: number, daysRemaining: number): BaseUnits {
  if (daysRemaining <= 0) {
    throw new RangeError('a target yield needs a positive number of days remaining');
  }
  const scale = 1_000_000n;
  const factor = 1 + (targetYieldPercent / 100) * (daysRemaining / DAYS_PER_YEAR);
  return mulDivRound(face, scale, BigInt(Math.round(factor * Number(scale))));
}

/**
 * Render a derived percentage.
 *
 * PRD section 12 rounds seeded yields to one decimal place; section 6 asks for
 * two decimals in summary views. The caller picks, and a null (at or after
 * maturity) renders as the maturity label instead of a number.
 */
export function formatPercent(value: number | null, decimals = 2): string {
  if (value === null) return '—';
  return `${value.toFixed(decimals)}%`;
}

/** The label shown where a forward yield would otherwise go. */
export function maturityLabel(state: MaturityState, settled: boolean): string {
  if (state === 'live') return 'Live';
  if (settled) return 'Settled';
  return state === 'due' ? 'Due' : 'Overdue';
}

/** True when `price` exceeds `face`, which no listing or bid may do. */
export function isAbovePar(face: BaseUnits, price: BaseUnits): boolean {
  return gt(price, face);
}

src/core/references.ts.source:
/**
 * The two reference numbers a preparer meets on PRD §8 screen 2.
 *
 * A payable carries the programme's own reference, `TP-2026-0141`, and the
 * supplier's invoice number, `INV-TW-88Q4A`. Both are sequential within their
 * series and both are generated the same way, by continuing from the highest
 * one already in use. That rule lived in three places before this module: a
 * regex in the create page and a `padStart` in each of the two entry forms.
 *
 * PRD §12 fixes the seeded `TP-2026-xxxx` numbers as identifiers rather than
 * live dates, so the year is part of the prefix and does not follow the clock.
 * The demo world's T0 moves; these do not.
 *
 * Suggesting rather than assigning. The database owns uniqueness: one unique
 * index guards the payable reference and another guards (supplier, invoice
 * reference), and `ledger.post()` refuses a collision by name. What these
 * functions buy is that a preparer creating the tenth payable of a demo does
 * not have to invent a number, and that the number offered is not one already
 * on the books.
 */

/** Payable references are four digits within the programme year. */
const PAYABLE_PREFIX = 'TP-2026-';
const PAYABLE_WIDTH = 4;

/** Invoice references are five digits behind the supplier's country code. */
const INVOICE_PREFIX = 'INV-TW-';
const INVOICE_WIDTH = 5;

/**
 * The next free number in a prefixed series.
 *
 * Only all-digit tails count toward the maximum. The seeded register contains
 * `INV-TW-88Q4A`, which is a real invoice number and not a member of any
 * sequence, so reading it as 88 would hand back a reference thousands below the
 * ones already issued.
 */
function nextInSeries(existing: Iterable<string>, prefix: string, width: number): string {
  const pattern = new RegExp(`^${prefix}(\\d+)$`);
  let highest = 0;
  for (const ref of existing) {
    const digits = pattern.exec(ref)?.[1];
    if (digits !== undefined) highest = Math.max(highest, Number(digits));
  }
  return `${prefix}${String(highest + 1).padStart(width, '0')}`;
}

/** The next programme reference, continuing the seeded `TP-2026-xxxx` series. */
export function nextPayableRef(existingRefs: Iterable<string>): string {
  return nextInSeries(existingRefs, PAYABLE_PREFIX, PAYABLE_WIDTH);
}

/**
 * An invoice reference the preparer can accept or type over.
 *
 * Feed it every reference the world knows, both the payables already raised and
 * the ERP register waiting to be imported. An unconsumed register row is a
 * reference about to exist, and suggesting it would collide the moment someone
 * imported that invoice for the same supplier.
 */
export function suggestInvoiceRef(existingRefs: Iterable<string>): string {
  return nextInSeries(existingRefs, INVOICE_PREFIX, INVOICE_WIDTH);
}

tests/techniques/equivalence-boundary.te.source:
/**
 * Equivalence partitioning and boundary value analysis, applied to field
 * validation.
 *
 * The artifact here is the two tables, not the runners. Each row names the
 * field under test, the equivalence class the input belongs to, where it sits
 * relative to a boundary, the input itself, and the single expected outcome.
 * Two loops turn the tables into cases, so adding a partition is adding a row.
 *
 * A boundary is always covered as a triple: the last value on one side, the
 * value on the edge, and the first value on the other. Rows carrying an `edge`
 * of `below` / `on` / `above` are those triples, and every one of them is
 * complete.
 *
 * A row with a `defect` is one where the system does not do what its own guard
 * says it does. Those rows state the CORRECT expectation and run under
 * `it.fails`, so the suite stays green while recording the defect. Each is
 * written up in tests/techniques/findings/equivalence-boundary.md under the id
 * the row carries.
 */

import { describe, it, expect, beforeAll, afterAll, afterEach } from 'vitest';
import {
  freshDatabase,
  post,
  anyActor,
  ledgerHealth,
  HEALTHY,
  type Database,
} from '../support/database';
import * as money from '@/core/money';
import * as fx from '@/core/fx';
import * as pricing from '@/core/pricing';
import * as clock from '@/core/clock';
import * as market from '@/core/market';

type Edge = 'below' | 'on' | 'above';

/** Exactly one of the two: a returned value, or a thrown class plus message. */
type Outcome =
  | { readonly value: unknown }
  | { readonly error: 'RangeError' | 'SyntaxError'; readonly message: string };

const returns = (value: unknown): Outcome => ({ value });
const rangeError = (message: string): Outcome => ({ error: 'RangeError', message });
const syntaxError = (message: string): Outcome => ({ error: 'SyntaxError', message });

interface PureCase {
  readonly field: string;
  readonly partition: string;
  readonly edge?: Edge;
  readonly input: string;
  readonly run: () => unknown;
  readonly expected: Outcome;
  readonly defect?: string;
}

/** Adopt a literal as base units without going through the decimal parser. */
const bu = (value: bigint) => money.fromBaseUnits(value);
const day = (text: string) => clock.parseIsoDate(text);

const MAX_SAFE = Number.MAX_SAFE_INTEGER;
const T0 = day('2026-01-01');

/** The five numbers a quote is actually read for; face, price and d echo back. */
const derived = (face: bigint, price: bigint, daysRemaining: number) => {
  const q = pricing.quote(bu(face), bu(price), daysRemaining);
  return {
    discount: q.discount,
    pricePercent: q.pricePercent,
    maturity: q.maturity,
    cost: q.annualisedDiscountCostPercent,
    lenderYield: q.lenderYieldPercent,
  };
};

const lot = (
  grade: string | null,
  face: bigint,
  maturityDate: string,
  daysRemaining: number,
  lenderYieldPercent: number | null,
  pricePercent: number,
): market.Filterable => ({
  grade,
  listedFaceBase: bu(face),
  maturityDate: day(maturityDate),
  quote: { daysRemaining, lenderYieldPercent, pricePercent },
});

const LOTS: readonly market.Filterable[] = [
  lot('AAA', 1_000n, '2026-03-01', 10, 9, 98),
  lot('AA', 2_000n, '2026-04-01', 30, 4, 99),
  lot('A', 3_000n, '2026-02-01', 0, null, 100),
  lot(null, 4_000n, '2026-05-01', 45, 6, 97),
];

const kept = (filter: Partial<market.MarketFilter>) =>
  market.applyFilter(LOTS, { ...market.NO_FILTER, ...filter }).map((l) => l.grade);

const PURE_CASES: readonly PureCase[] = [
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: whole digits only',
    input: '"250000"',
    run: () => money.parseUnits('250000'),
    expected: returns(2_500_000_000n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: zero',
    input: '"0"',
    run: () => money.parseUnits('0'),
    expected: returns(0n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: leading zeros are not an error',
    input: '"007"',
    run: () => money.parseUnits('007'),
    expected: returns(70_000n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: trailing point with an empty fraction',
    input: '"5."',
    run: () => money.parseUnits('5.'),
    expected: returns(50_000n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: surrounding whitespace is trimmed',
    input: '"  12.5  "',
    run: () => money.parseUnits('  12.5  '),
    expected: returns(125_000n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: negative',
    input: '"-0.0001"',
    run: () => money.parseUnits('-0.0001'),
    expected: returns(-1n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: negative zero collapses to zero',
    input: '"-0"',
    run: () => money.parseUnits('-0'),
    expected: returns(0n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'valid: smallest representable magnitude',
    input: '"0.0001"',
    run: () => money.parseUnits('0.0001'),
    expected: returns(1n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'fraction length under the 4-decimal limit',
    edge: 'below',
    input: '"1.234"',
    run: () => money.parseUnits('1.234'),
    expected: returns(12_340n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'fraction length exactly at the 4-decimal limit',
    edge: 'on',
    input: '"1.2345"',
    run: () => money.parseUnits('1.2345'),
    expected: returns(12_345n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'fraction one past the limit, excess digit zero',
    edge: 'above',
    input: '"1.23450"',
    run: () => money.parseUnits('1.23450'),
    expected: returns(12_345n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'fraction one past the limit, excess digit non-zero',
    edge: 'above',
    input: '"1.23456"',
    run: () => money.parseUnits('1.23456'),
    expected: rangeError(
      '1.23456 needs more than 4 decimals; amounts between base units are not representable',
    ),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'far past the limit but every excess digit zero',
    input: '"1.50000000"',
    run: () => money.parseUnits('1.50000000'),
    expected: returns(15_000n),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'smallest value below one base unit',
    input: '"0.00005"',
    run: () => money.parseUnits('0.00005'),
    expected: rangeError(
      '0.00005 needs more than 4 decimals; amounts between base units are not representable',
    ),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'negative, excess digit non-zero',
    input: '"-1.00001"',
    run: () => money.parseUnits('-1.00001'),
    expected: rangeError(
      '-1.00001 needs more than 4 decimals; amounts between base units are not representable',
    ),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: exponent notation',
    input: '"1e5"',
    run: () => money.parseUnits('1e5'),
    expected: rangeError('not a decimal amount: "1e5"'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: empty',
    input: '""',
    run: () => money.parseUnits(''),
    expected: rangeError('not a decimal amount: ""'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: whitespace only, reported untrimmed',
    input: '"  "',
    run: () => money.parseUnits('  '),
    expected: rangeError('not a decimal amount: "  "'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: explicit plus sign',
    input: '"+1"',
    run: () => money.parseUnits('+1'),
    expected: rangeError('not a decimal amount: "+1"'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: leading point, no whole part',
    input: '".5"',
    run: () => money.parseUnits('.5'),
    expected: rangeError('not a decimal amount: ".5"'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: thousands separator',
    input: '"1,000"',
    run: () => money.parseUnits('1,000'),
    expected: rangeError('not a decimal amount: "1,000"'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: sign with no digits',
    input: '"-"',
    run: () => money.parseUnits('-'),
    expected: rangeError('not a decimal amount: "-"'),
  },
  {
    field: 'money.parseUnits(input)',
    partition: 'not a decimal: a number-like word',
    input: '"Infinity"',
    run: () => money.parseUnits('Infinity'),
    expected: rangeError('not a decimal amount: "Infinity"'),
  },
  {
    field: 'money.parseUnits(input)',
